/**
 * The plan API (/api/ev/plan, webapp/evplan.py). Types are written here because the generated schema
 * (src/api/schema.d.ts, `npm run gen:api`) is regenerated by the integration step, not by this page.
 */
import { useMutation, useQuery } from "@tanstack/react-query"

import { ApiError, apiUrl, getJson, postJson } from "@/api/client"

export interface PlanDecision {
  id: string
  type: "must_match" | "counts_as" | "threshold" | "include"
  value: unknown
  reason: string
  flagged: boolean
  flag_reason: string | null
  confirmed_by: string | null
  confirmed_at: string | null
}

export interface PlanLine {
  id: string
  question: string
  query: string
  template: string | null
  removable: boolean
}

export interface PlanData {
  question: string
  field: string
  lines: PlanLine[]
  main_rule: string
  decisions: PlanDecision[]
  clarifications: Record<string, string>[]
}

export interface Clarification {
  question: string
  options: string[]
}

export interface PlanView {
  id: string
  question: string
  clarifications: Clarification[]
  plan: PlanData | null
  /** Per line id: plain sentences for "how?" (never code). */
  how: Record<string, string[]>
  /** What the backend's code checks found wrong; the plan cannot run while there is any. */
  problems: string[]
  /** Every decision confirmed and no problem (the backend's rule). */
  ready: boolean
  frozen: boolean
  run: string | null
}

export interface LineResult {
  id: string
  question: string
  status: "done" | "failed"
  rows: Record<string, unknown>[]
  text: string
}

/** The main-answer rules (mirror of evidence/planner RULES; the backend refuses any other). */
export const RULES: Record<string, string> = {
  any_line: "yes when any line found evidence",
  all_lines: "yes when every line found evidence",
  majority: "yes when more than half of the lines found evidence",
}
export const MAIN_RULE_ID = "main_rule"

/** What the person typed as a decision's value: JSON when it is JSON (0.05, ["a"]), else the text. */
export function parseValue(text: string): unknown {
  try {
    return JSON.parse(text)
  } catch {
    return text
  }
}

export interface Rerun {
  setting: string
  flips: boolean
  [key: string]: unknown
}

export interface PlanResult {
  status?: "running" | "done"
  lines: LineResult[]
  answer: { text: string; missing?: string[]; main_rule?: string | null; rule_met?: boolean | null; found?: string[] }
  reruns?: Rerun[]
}

const base = (id: string) => `/api/ev/plan/${encodeURIComponent(id)}`

export const startPlan = (question: string) => postJson<PlanView>("/api/ev/plan", { question })
export const sendAnswers = (id: string, answers: { question: string; answer: string }[]) => postJson<PlanView>(`${base(id)}/clarify`, { answers })
export const decide = (id: string, did: string, body: { confirm: true } | { change: unknown }) => postJson<PlanView>(`${base(id)}/decision/${encodeURIComponent(did)}`, body)
export const confirmAll = (id: string) => postJson<PlanView>(`${base(id)}/confirm-all`, {})
export const setMainRule = (id: string, rule: string) => postJson<PlanView>(`${base(id)}/main-rule`, { rule })
export const startRun = (id: string) => postJson<{ run: string }>(`${base(id)}/run`, {})

/** DELETE with the header the backend's guard asks of a write that has no JSON body. */
export async function deleteLine(id: string, lid: string): Promise<PlanView> {
  const path = `${base(id)}/line/${encodeURIComponent(lid)}`
  const response = await fetch(apiUrl(path), { method: "DELETE", headers: { Accept: "application/json", "X-Requested-With": "plan-page" } })
  const data: unknown = await response.json().catch(() => ({}))
  if (!response.ok) {
    const detail = typeof data === "object" && data && "detail" in data ? String((data as { detail: unknown }).detail) : response.statusText
    throw new ApiError(response.status, path, detail, data)
  }
  return data as PlanView
}

/** The run's result; polls while the run is going. */
export function usePlanResult(id: string | null, started: boolean) {
  return useQuery({
    queryKey: ["plan-result", id],
    queryFn: () => getJson<PlanResult>(`${base(id as string)}/result`),
    enabled: id !== null && started,
    refetchInterval: (query) => (query.state.data?.status === "running" ? 2000 : false),
  })
}

export function useAction<A, R = PlanView>(fn: (arg: A) => Promise<R>, onDone: (r: R) => void, onError: (e: unknown) => void) {
  return useMutation({ mutationFn: fn, onSuccess: onDone, onError })
}
